import os
from pathlib import Path

import pytest

NOTES_DIR = "notes"


def read_public(path: str) -> str:
    """Return the text of the file `path` inside the directory `notes`.

    `notes` is relative to the current working directory. `path` is an
    untrusted request path. Paths that wander but stay inside `notes`
    (e.g. "sub/../a.txt") are allowed. Any path that leaves `notes`
    (e.g. "..", "sub/../../x", or an absolute path), including through
    symlinks, reads nothing and yields "". A missing, unreadable, or
    non-file target, an empty path, or a name containing a NUL byte
    also yields "".
    """
    if not path or "\x00" in path:
        return ""
    try:
        if os.path.isabs(path) or Path(path).anchor or Path(path).drive:
            return ""
        base = Path(NOTES_DIR).resolve()
        current = base
        for part in Path(path).parts:
            if part in ("", "."):
                continue
            if not current.is_dir():
                return ""
            if part == "..":
                current = current.parent
            else:
                current = (current / part).resolve()
            if not current.is_relative_to(base):
                return ""
        if current == base or not current.is_file():
            return ""
        with open(current, encoding="utf-8", errors="replace") as f:
            return f.read()
    except (OSError, ValueError, RuntimeError):
        return ""


@pytest.fixture
def sandbox(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    notes = tmp_path / NOTES_DIR
    (notes / "sub").mkdir(parents=True)
    (notes / "a.txt").write_text("alpha", encoding="utf-8")
    (notes / "sub" / "b.txt").write_text("beta", encoding="utf-8")
    (tmp_path / "secret.txt").write_text("SECRET", encoding="utf-8")
    evil = tmp_path / "notes_evil"
    evil.mkdir()
    (evil / "x.txt").write_text("EVIL", encoding="utf-8")
    monkeypatch.chdir(tmp_path)
    return tmp_path


def test_reads_plain_file(sandbox: Path) -> None:
    assert read_public("a.txt") == "alpha"


def test_reads_nested_file(sandbox: Path) -> None:
    assert read_public("sub/b.txt") == "beta"


def test_wander_and_return_is_allowed(sandbox: Path) -> None:
    assert read_public("sub/../a.txt") == "alpha"
    assert read_public("./sub/./b.txt") == "beta"
    assert read_public("sub/../sub/b.txt") == "beta"


def test_missing_file(sandbox: Path) -> None:
    assert read_public("nope.txt") == ""
    assert read_public("sub/nope.txt") == ""
    assert read_public("nodir/a.txt") == ""


def test_empty_and_directory_paths(sandbox: Path) -> None:
    assert read_public("") == ""
    assert read_public(".") == ""
    assert read_public("sub") == ""
    assert read_public("sub/") == ""


def test_dotdot_escapes(sandbox: Path) -> None:
    assert read_public("..") == ""
    assert read_public("../secret.txt") == ""
    assert read_public("sub/../../secret.txt") == ""
    assert read_public("sub/../../notes/../secret.txt") == ""
    assert read_public("a.txt/../../secret.txt") == ""


def test_dotdot_into_sibling_with_same_prefix(sandbox: Path) -> None:
    assert read_public("../notes_evil/x.txt") == ""


def test_absolute_paths(sandbox: Path) -> None:
    assert read_public(str(sandbox / "secret.txt")) == ""
    assert read_public(str(sandbox / NOTES_DIR / "a.txt")) == ""
    assert read_public("/etc/passwd") == ""
    assert read_public("/") == ""


def test_leading_slashes_do_not_reach_outside(sandbox: Path) -> None:
    assert read_public("//etc/passwd") == ""
    assert read_public("/" + str(sandbox / "secret.txt")) == ""


def test_nul_byte(sandbox: Path) -> None:
    assert read_public("a.txt\x00../secret.txt") == ""
    assert read_public("a\x00.txt") == ""


def test_symlink_file_escaping(sandbox: Path) -> None:
    link = sandbox / NOTES_DIR / "link.txt"
    try:
        os.symlink(sandbox / "secret.txt", link)
    except (OSError, NotImplementedError):
        pytest.skip("symlinks not supported")
    assert read_public("link.txt") == ""


def test_symlink_dir_escaping(sandbox: Path) -> None:
    link = sandbox / NOTES_DIR / "out"
    try:
        os.symlink(sandbox, link, target_is_directory=True)
    except (OSError, NotImplementedError):
        pytest.skip("symlinks not supported")
    assert read_public("out/secret.txt") == ""
    assert read_public("out/notes/a.txt") == ""


def test_symlink_relative_escaping(sandbox: Path) -> None:
    link = sandbox / NOTES_DIR / "rel.txt"
    try:
        os.symlink("../secret.txt", link)
    except (OSError, NotImplementedError):
        pytest.skip("symlinks not supported")
    assert read_public("rel.txt") == ""


def test_returns_str_for_non_utf8_file(sandbox: Path) -> None:
    (sandbox / NOTES_DIR / "bin.dat").write_bytes(b"\xff\xfe\x00\x80")
    assert isinstance(read_public("bin.dat"), str)
